def eulerian_num(n, m):
    if m == 0 or m == n:
        return 1
    if m == 1 or m == n - 1:
        return 2 ** (n - 1) - 1
    if m > n:
        return 0

    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 1
        dp[i][i] = 1

    for i in range(2, n + 1):
        for j in range(1, i):
            dp[i][j] = (j + 1) * dp[i - 1][j] + i * dp[i - 1][j - 1]

    return dp[n][m]

